#!/usr/bin/env bash
#
# Build a browsable TYPO3 demo instance for manually testing EXT:headliner.
#
# Run from the project root with DDEV:
#     ddev composer install
#     ddev exec bash Build/Scripts/setup-demo-instance.sh
#
# Afterwards:
#     Frontend: https://headliner.ddev.site/
#     Backend:  https://headliner.ddev.site/typo3/   (user admin, random password printed at the end)
#
# The instance itself (config/, .Build/, var/, fileadmin uploads, database) is git-ignored and
# fully regenerated by this script — re-run it any time to get a clean instance.

set -euo pipefail

# Environment-parameterised so the same script seeds the DDEV demo (defaults below) and any CI
# instance (native MariaDB creds + a localhost BASE_URL).
BASE_URL="${BASE_URL:-https://${DDEV_SITENAME:-headliner}.ddev.site/}"
ADMIN_USER="${ADMIN_USER:-admin}"
# Local demo only: fixed default password unless ADMIN_PASS is given (e.g. by CI).
ADMIN_PASS="${ADMIN_PASS:-Password.1}"
DB_HOST="${DB_HOST:-db}"
DB_PORT="${DB_PORT:-3306}"
DB_NAME="${DB_NAME:-db}"
DB_USER="${DB_USER:-db}"
DB_PASS="${DB_PASS:-db}"
DB_ROOT_USER="${DB_ROOT_USER:-root}"
DB_ROOT_PASS="${DB_ROOT_PASS:-root}"

# Path-parameterised so the script can also seed another TYPO3 install (set TYPO3_BIN, default: .Build/bin/typo3).
TYPO3_BIN="${TYPO3_BIN:-.Build/bin/typo3}"

echo "› resetting the database for a clean install"
mysql -h "${DB_HOST}" -P "${DB_PORT}" -u "${DB_ROOT_USER}" -p"${DB_ROOT_PASS}" \
    -e "DROP DATABASE IF EXISTS \`${DB_NAME}\`; CREATE DATABASE \`${DB_NAME}\` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;" 2>/dev/null

echo "› TYPO3 setup (database + admin user + site)"
"${TYPO3_BIN}" setup \
    --driver=mysqli --host="${DB_HOST}" --port="${DB_PORT}" --dbname="${DB_NAME}" --username="${DB_USER}" --password="${DB_PASS}" \
    --admin-username="${ADMIN_USER}" --admin-user-password="${ADMIN_PASS}" --admin-email=admin@example.com \
    --project-name=headliner --create-site="${BASE_URL}" --server-type=other --no-interaction --force
# The tables of the demo packages (the child records of the demo content elements) are created from their TCA
"${TYPO3_BIN}" database:updateschema

# Persist trusted hosts into settings.php (not additional.php, which DDEV manages for the default
# docroot). DDEV only writes its additional.php once the docroot exists at `ddev start`, so a
# first-run or volume install would otherwise reject the host (#1396795884). Writing settings.php
# makes every instance self-sufficient with no restart. (TYPO3_CONTEXT=Development from
# web_environment already gives the debug error page.)
echo "› configuring trusted hosts in settings.php"
"${TYPO3_BIN}" configuration:set SYS/trustedHostsPattern '.*'

# Render the frontend with fluid_styled_content and EXT:headliner (site sets), and seed content with a
# deliberately uneven heading structure: an H2 followed by an H4 (skipped level) and a "div" header.
echo "› enabling the site sets and seeding demo content"
SITE_CONFIG="$(ls config/sites/*/config.yaml | head -1)"
# The demo's content is in <main>
cat >> "$(dirname "${SITE_CONFIG}")/settings.yaml" <<'SETTINGS'

headliner:
  contentSelector: main
SETTINGS
# A header and a footer with an h2 each around the content, which is in <main>, as in most themes: the box shows the
# headings around the content (site setting headliner.contentSelector) very pale and does not check them. An h1 in the
# header would count as the h1 of the page, so the pages with one h1 in their content would have two.
cat >> "$(dirname "${SITE_CONFIG}")/setup.typoscript" <<'TYPOSCRIPT'

page.10.stdWrap.wrap = <div style="max-width: 800px; margin: 2em auto;"><header><h2>Demo site</h2></header><main>|</main><footer><h2>Contact us</h2></footer></div>
TYPOSCRIPT
# German as second language (base /de/), to test translations
sed -i '/^    flag: us$/a\  -\n    title: Deutsch\n    enabled: true\n    languageId: 1\n    base: /de/\n    locale: de_DE.UTF-8\n    navigationTitle: Deutsch\n    flag: de\n    fallbackType: strict' "${SITE_CONFIG}"
# The demo of a content element with child records, made with the means of the core (package twtgroup/headliner-demo,
# which has a site set of its own), if it is installed
DEMO_DEPENDENCY=""
if [ -d .Build/vendor/twtgroup/headliner-demo ]; then
    DEMO_DEPENDENCY='\n  - twtgroup/headliner-demo'
fi
if grep -q '^dependencies: {  }$' "${SITE_CONFIG}"; then
    sed -i "s#^dependencies: {  }\$#dependencies:\n  - typo3/fluid-styled-content\n  - twtgroup/headliner-fluid-styled-content${DEMO_DEPENDENCY}#" "${SITE_CONFIG}"
else
    # `typo3 setup` already lists the fluid_styled_content sets; add ours to that list
    sed -i "s#^dependencies:\$#dependencies:\n  - twtgroup/headliner-fluid-styled-content${DEMO_DEPENDENCY}#" "${SITE_CONFIG}"
fi
mysql -h "${DB_HOST}" -P "${DB_PORT}" -u "${DB_USER}" -p"${DB_PASS}" "${DB_NAME}" -e "
    INSERT INTO tt_content (pid, CType, colPos, sorting, sys_language_uid, header, header_layout, header_tag, subheader, subheader_tag, bodytext, crdate, tstamp) VALUES
        (1, 'header', 0, 512, 0, 'Our services', 2, 'h2', 'What we do', 'h3', '', UNIX_TIMESTAMP(), UNIX_TIMESTAMP()),
        (1, 'text', 0, 768, 0, 'Details', 2, 'h4', '', 'h3', '<p>Tag H4 with the look of layout 2: the last heading was an H2, so a level is skipped.</p>', UNIX_TIMESTAMP(), UNIX_TIMESTAMP()),
        (1, 'text', 0, 1024, 0, 'Looks like a heading, is none', 2, 'div', '', 'h3', '<p>Tag div chosen: styled like layout 2, but no heading.</p>', UNIX_TIMESTAMP(), UNIX_TIMESTAMP());
" 2>/dev/null

# Subpages with different heading structures, so every case of the page module has something to show.
echo "› creating demo subpages"
mysql -h "${DB_HOST}" -P "${DB_PORT}" -u "${DB_USER}" -p"${DB_PASS}" "${DB_NAME}" -e "
    INSERT INTO pages (pid, title, slug, doktype, sorting, perms_userid, perms_groupid, perms_user, perms_group, perms_everybody, crdate, tstamp) VALUES
        (1, 'About us', '/about', 1, 256, 1, 0, 31, 27, 0, UNIX_TIMESTAMP(), UNIX_TIMESTAMP());
    SET @about = LAST_INSERT_ID();
    INSERT INTO pages (pid, title, slug, doktype, sorting, perms_userid, perms_groupid, perms_user, perms_group, perms_everybody, crdate, tstamp) VALUES
        (1, 'Products', '/products', 1, 512, 1, 0, 31, 27, 0, UNIX_TIMESTAMP(), UNIX_TIMESTAMP());
    SET @products = LAST_INSERT_ID();
    INSERT INTO pages (pid, title, slug, doktype, sorting, perms_userid, perms_groupid, perms_user, perms_group, perms_everybody, crdate, tstamp) VALUES
        (1, 'Services', '/services', 1, 768, 1, 0, 31, 27, 0, UNIX_TIMESTAMP(), UNIX_TIMESTAMP());
    SET @services = LAST_INSERT_ID();
    INSERT INTO pages (pid, title, slug, doktype, sorting, perms_userid, perms_groupid, perms_user, perms_group, perms_everybody, crdate, tstamp) VALUES
        (@services, 'Web development', '/services/web-development', 1, 256, 1, 0, 31, 27, 0, UNIX_TIMESTAMP(), UNIX_TIMESTAMP());
    SET @webdev = LAST_INSERT_ID();
    INSERT INTO pages (pid, title, slug, doktype, sorting, perms_userid, perms_groupid, perms_user, perms_group, perms_everybody, crdate, tstamp) VALUES
        (1, 'Contact', '/contact', 1, 1024, 1, 0, 31, 27, 0, UNIX_TIMESTAMP(), UNIX_TIMESTAMP());
    SET @contact = LAST_INSERT_ID();
    INSERT INTO pages (pid, title, slug, doktype, sorting, perms_userid, perms_groupid, perms_user, perms_group, perms_everybody, crdate, tstamp) VALUES
        (1, 'Legal notice', '/legal', 1, 1280, 1, 0, 31, 27, 0, UNIX_TIMESTAMP(), UNIX_TIMESTAMP());
    SET @legal = LAST_INSERT_ID();

    INSERT INTO tt_content (pid, CType, colPos, sorting, sys_language_uid, header, header_layout, header_tag, subheader, subheader_tag, bodytext, crdate, tstamp) VALUES
        -- About us: a clean structure (H1, H2, H3, H2)
        (@about, 'text', 0, 256, 0, 'About us', 1, 'h1', 'Who we are', 'h2', '<p>A clean heading structure: nothing to fix here.</p>', UNIX_TIMESTAMP(), UNIX_TIMESTAMP()),
        (@about, 'text', 0, 512, 0, 'Our history', 2, 'h2', '', 'h3', '<p>Founded a long time ago.</p>', UNIX_TIMESTAMP(), UNIX_TIMESTAMP()),
        (@about, 'text', 0, 768, 0, 'The early years', 3, 'h3', '', 'h3', '<p>Small team, big ideas.</p>', UNIX_TIMESTAMP(), UNIX_TIMESTAMP()),
        (@about, 'text', 0, 1024, 0, 'Our team', 2, 'h2', '', 'h3', '<p>Meet the people behind it.</p>', UNIX_TIMESTAMP(), UNIX_TIMESTAMP()),
        -- Products: two H1 and a skipped level
        (@products, 'text', 0, 256, 0, 'Products', 1, 'h1', '', 'h3', '<p>The first H1.</p>', UNIX_TIMESTAMP(), UNIX_TIMESTAMP()),
        (@products, 'text', 0, 512, 0, 'Our bestsellers', 1, 'h1', '', 'h3', '<p>A second H1 on the same page.</p>', UNIX_TIMESTAMP(), UNIX_TIMESTAMP()),
        (@products, 'text', 0, 768, 0, 'Product details', 2, 'h4', '', 'h3', '<p>An H4 right after an H1: two levels skipped.</p>', UNIX_TIMESTAMP(), UNIX_TIMESTAMP()),
        -- Services: no H1, starts with an H2, and a header that is only a div
        (@services, 'text', 0, 256, 0, 'What we offer', 2, 'h2', 'For every size of company', 'h3', '<p>This page has no H1.</p>', UNIX_TIMESTAMP(), UNIX_TIMESTAMP()),
        (@services, 'text', 0, 512, 0, 'Consulting', 2, 'div', '', 'h3', '<p>Styled like a heading, but a div: it is not part of the structure.</p>', UNIX_TIMESTAMP(), UNIX_TIMESTAMP()),
        (@services, 'text', 0, 768, 0, 'Support', 2, 'h2', '', 'h3', '<p>Help when you need it.</p>', UNIX_TIMESTAMP(), UNIX_TIMESTAMP()),
        -- Web development (subpage of Services): header and subheader with their own tags
        (@webdev, 'text', 0, 256, 0, 'Web development', 1, 'h1', 'Websites that work', 'h2', '<p>Header H1 (layout 1), subheader H2 (layout 2).</p>', UNIX_TIMESTAMP(), UNIX_TIMESTAMP()),
        (@webdev, 'text', 0, 512, 0, 'Technology', 2, 'h2', 'Our stack', 'div', '<p>The subheader here is a div, so it is no heading.</p>', UNIX_TIMESTAMP(), UNIX_TIMESTAMP()),
        -- Contact: headings that come from the text (RTE), which the page module shows but cannot edit
        (@contact, 'text', 0, 256, 0, 'Contact', 1, 'h1', '', 'h3', '<h2>Visit us</h2><p>Main street 1</p><h3>Opening hours</h3><p>Mon-Fri 9-17</p><h2>Write to us</h2><p>mail@example.com</p>', UNIX_TIMESTAMP(), UNIX_TIMESTAMP()),
        -- Legal notice: no heading at all
        (@legal, 'text', 0, 256, 0, '', 0, 'h2', '', 'h3', '<p>A page without any heading.</p>', UNIX_TIMESTAMP(), UNIX_TIMESTAMP());
" 2>/dev/null

# German translation of the main pages and their content elements. Header tags and layouts are copied from the original.
echo "› creating the German translation"
mysql -h "${DB_HOST}" -P "${DB_PORT}" -u "${DB_USER}" -p"${DB_PASS}" "${DB_NAME}" -e "
    -- pages
    INSERT INTO pages (pid, title, slug, doktype, sorting, sys_language_uid, l10n_parent, l10n_source, perms_userid, perms_groupid, perms_user, perms_group, perms_everybody, crdate, tstamp)
    SELECT pid, 'Startseite', '/', doktype, sorting, 1, uid, uid, perms_userid, perms_groupid, perms_user, perms_group, perms_everybody, UNIX_TIMESTAMP(), UNIX_TIMESTAMP() FROM pages WHERE slug = '/' AND sys_language_uid = 0;
    INSERT INTO pages (pid, title, slug, doktype, sorting, sys_language_uid, l10n_parent, l10n_source, perms_userid, perms_groupid, perms_user, perms_group, perms_everybody, crdate, tstamp)
    SELECT pid, 'Über uns', '/ueber-uns', doktype, sorting, 1, uid, uid, perms_userid, perms_groupid, perms_user, perms_group, perms_everybody, UNIX_TIMESTAMP(), UNIX_TIMESTAMP() FROM pages WHERE slug = '/about' AND sys_language_uid = 0;
    INSERT INTO pages (pid, title, slug, doktype, sorting, sys_language_uid, l10n_parent, l10n_source, perms_userid, perms_groupid, perms_user, perms_group, perms_everybody, crdate, tstamp)
    SELECT pid, 'Produkte', '/produkte', doktype, sorting, 1, uid, uid, perms_userid, perms_groupid, perms_user, perms_group, perms_everybody, UNIX_TIMESTAMP(), UNIX_TIMESTAMP() FROM pages WHERE slug = '/products' AND sys_language_uid = 0;
    INSERT INTO pages (pid, title, slug, doktype, sorting, sys_language_uid, l10n_parent, l10n_source, perms_userid, perms_groupid, perms_user, perms_group, perms_everybody, crdate, tstamp)
    SELECT pid, 'Kontakt', '/kontakt', doktype, sorting, 1, uid, uid, perms_userid, perms_groupid, perms_user, perms_group, perms_everybody, UNIX_TIMESTAMP(), UNIX_TIMESTAMP() FROM pages WHERE slug = '/contact' AND sys_language_uid = 0;

    -- content elements: structure (type, column, tag, layouts) from the original, texts in German
    INSERT INTO tt_content (pid, sys_language_uid, l18n_parent, l10n_source, CType, colPos, sorting, header, header_layout, header_tag, subheader, subheader_tag, bodytext, crdate, tstamp)
    SELECT pid, 1, uid, uid, CType, colPos, sorting,
        CASE header
            WHEN 'Our services' THEN 'Unsere Leistungen'
            WHEN 'Details' THEN 'Einzelheiten'
            WHEN 'Looks like a heading, is none' THEN 'Sieht aus wie eine Überschrift, ist keine'
            WHEN 'About us' THEN 'Über uns'
            WHEN 'Our history' THEN 'Unsere Geschichte'
            WHEN 'The early years' THEN 'Die ersten Jahre'
            WHEN 'Our team' THEN 'Unser Team'
            WHEN 'Products' THEN 'Produkte'
            WHEN 'Our bestsellers' THEN 'Unsere Bestseller'
            WHEN 'Product details' THEN 'Produktdetails'
            WHEN 'Contact' THEN 'Kontakt'
            ELSE 'Willkommen auf Ihrer Standardwebsite'
        END,
        header_layout, header_tag,
        CASE subheader WHEN 'What we do' THEN 'Was wir tun' WHEN 'Who we are' THEN 'Wer wir sind' ELSE subheader END,
        subheader_tag,
        CASE
            WHEN header = 'Contact' THEN '<h2>Besuchen Sie uns</h2><p>Hauptstraße 1</p><h3>Öffnungszeiten</h3><p>Mo-Fr 9-17</p><h2>Schreiben Sie uns</h2><p>mail@example.com</p>'
            WHEN bodytext = '' OR bodytext IS NULL THEN bodytext
            ELSE CONCAT('<p>Deutsche Übersetzung: ', REGEXP_REPLACE(bodytext, '<[^>]+>', ''), '</p>')
        END,
        UNIX_TIMESTAMP(), UNIX_TIMESTAMP()
    FROM tt_content
    WHERE sys_language_uid = 0 AND pid IN (SELECT uid FROM pages WHERE slug IN ('/', '/about', '/products', '/contact') AND sys_language_uid = 0);
" 2>/dev/null

# A workspace with a draft: in it the home page has an H1 (the live page has none). Done after the translation, which
# would copy the version, too.
echo "› creating a workspace with a draft version"
mysql -h "${DB_HOST}" -P "${DB_PORT}" -u "${DB_USER}" -p"${DB_PASS}" "${DB_NAME}" -e "
    INSERT INTO sys_workspace (pid, title, adminusers, members, db_mountpoints, tstamp) VALUES (0, 'Review', '', '', '', UNIX_TIMESTAMP());
    SET @ws = LAST_INSERT_ID();
    INSERT INTO tt_content (pid, CType, colPos, sorting, sys_language_uid, header, header_layout, header_tag, subheader, subheader_tag, bodytext, t3ver_oid, t3ver_wsid, t3ver_state, crdate, tstamp)
    SELECT pid, CType, colPos, sorting, sys_language_uid, 'Our services (draft)', header_layout, 'h1', subheader, subheader_tag, bodytext, uid, @ws, 0, UNIX_TIMESTAMP(), UNIX_TIMESTAMP()
    FROM tt_content WHERE header = 'Our services' AND sys_language_uid = 0 AND t3ver_wsid = 0;
" 2>/dev/null

# SQL as the demo user. Unlike the seeds above, errors are shown: these seeds depend on packages that may be missing.
demo_sql() {
    mysql -h "${DB_HOST}" -P "${DB_PORT}" -u "${DB_USER}" -p"${DB_PASS}" "${DB_NAME}" "$@"
}
demo_has_table() {
    [ -n "$(demo_sql -N -e "SHOW TABLES LIKE '$1'")" ]
}

# A content element with child records (IRRE) made with the means of the core, no Content Blocks: the wrapper
# headliner:headline.children, the tag field of a record, the heading in a rich text of a record. Package
# twtgroup/headliner-demo (Build/Demo/headliner_demo).
if demo_has_table tx_headlinerdemo_item; then
    echo "› creating the demo of child records (core)"
    demo_sql -e "
        INSERT INTO pages (pid, title, slug, doktype, sorting, perms_userid, perms_groupid, perms_user, perms_group, perms_everybody, crdate, tstamp) VALUES
            (1, 'Teaser (core IRRE)', '/teaser', 1, 1024, 1, 0, 31, 27, 0, UNIX_TIMESTAMP(), UNIX_TIMESTAMP());
        SET @page = LAST_INSERT_ID();
        INSERT INTO tt_content (pid, CType, colPos, sorting, sys_language_uid, header, header_layout, header_tag, headlinerdemo_items, crdate, tstamp)
            VALUES (@page, 'headlinerdemo_teaser', 0, 256, 0, 'Teaser list', 0, 'h2', 3, UNIX_TIMESTAMP(), UNIX_TIMESTAMP());
        SET @element = LAST_INSERT_ID();
        INSERT INTO tx_headlinerdemo_item (pid, sorting, title, tag, text, parent, crdate, tstamp) VALUES
            (@page, 256, 'First teaser', 'h3', '<p>A teaser from a plain TCA table.</p>', @element, UNIX_TIMESTAMP(), UNIX_TIMESTAMP()),
            (@page, 512, 'Second teaser', 'h3', '<p>No heading in this text.</p>', @element, UNIX_TIMESTAMP(), UNIX_TIMESTAMP()),
            (@page, 768, 'Third teaser', 'h4', '<h3>A heading in the text of a teaser</h3><p>Text.</p>', @element, UNIX_TIMESTAMP(), UNIX_TIMESTAMP());
    "
fi

# The same with Content Blocks (cards, a slider) and the Visual Editor, if `ddev demo --extras` installed them
# (package twtgroup/headliner-demo-blocks, Build/Demo/headliner_demo_blocks).
if demo_has_table cards && demo_has_table slides; then
    echo "› creating the demo of the Content Blocks (cards, slider)"
    demo_sql -e "
        INSERT INTO pages (pid, title, slug, doktype, sorting, perms_userid, perms_groupid, perms_user, perms_group, perms_everybody, crdate, tstamp) VALUES
            (1, 'Cards (Content Block)', '/cards', 1, 1280, 1, 0, 31, 27, 0, UNIX_TIMESTAMP(), UNIX_TIMESTAMP());
        SET @page = LAST_INSERT_ID();
        INSERT INTO tt_content (pid, CType, colPos, sorting, sys_language_uid, header, header_layout, header_tag, cards, crdate, tstamp)
            VALUES (@page, 'twtgroup_cards', 0, 256, 0, 'Our cards', 0, 'h2', 3, UNIX_TIMESTAMP(), UNIX_TIMESTAMP());
        SET @element = LAST_INSERT_ID();
        INSERT INTO cards (pid, sorting, title, tag, text, foreign_table_parent_uid, crdate, tstamp) VALUES
            (@page, 256, 'First card', 'h3', '<p>The first card has an H3.</p>', @element, UNIX_TIMESTAMP(), UNIX_TIMESTAMP()),
            (@page, 512, 'Second card', 'h3', '<p>The second card has an H3 as well.</p>', @element, UNIX_TIMESTAMP(), UNIX_TIMESTAMP()),
            (@page, 768, 'Third card', 'h4', '<h3>A heading in the text of a card</h3><p>An H4 right after an H2: a level is skipped.</p>', @element, UNIX_TIMESTAMP(), UNIX_TIMESTAMP());

        INSERT INTO pages (pid, title, slug, doktype, sorting, perms_userid, perms_groupid, perms_user, perms_group, perms_everybody, crdate, tstamp) VALUES
            (1, 'Slider (Content Block)', '/slider', 1, 1536, 1, 0, 31, 27, 0, UNIX_TIMESTAMP(), UNIX_TIMESTAMP());
        SET @page = LAST_INSERT_ID();
        INSERT INTO tt_content (pid, CType, colPos, sorting, sys_language_uid, header, header_layout, header_tag, slides, crdate, tstamp)
            VALUES (@page, 'twtgroup_slider', 0, 256, 0, 'Our slider', 0, 'h2', 3, UNIX_TIMESTAMP(), UNIX_TIMESTAMP());
        SET @element = LAST_INSERT_ID();
        INSERT INTO slides (pid, sorting, title, tag, text, foreign_table_parent_uid, crdate, tstamp) VALUES
            (@page, 256, 'First slide', 'h3', '<p>The first slide has an H3.</p>', @element, UNIX_TIMESTAMP(), UNIX_TIMESTAMP()),
            (@page, 512, 'Second slide', 'h3', '<p>A slide without a heading in its text.</p>', @element, UNIX_TIMESTAMP(), UNIX_TIMESTAMP()),
            (@page, 768, 'Third slide', 'h4', '<h3>A heading in the text of a slide</h3><p>An H4 title and an H3 in the text.</p><h4>And another one</h4>', @element, UNIX_TIMESTAMP(), UNIX_TIMESTAMP());
    "
fi

# The same cards once more, but the template gives the record to the ViewHelper (`record="{card}" tagField="tag"`) instead of
# the values (block recordcards, same package).
if demo_has_table recordcards; then
    echo "› creating the demo of the Content Block with the record (cards, record variant)"
    demo_sql -e "
        INSERT INTO pages (pid, title, slug, doktype, sorting, perms_userid, perms_groupid, perms_user, perms_group, perms_everybody, crdate, tstamp) VALUES
            (1, 'Cards with record (Content Block)', '/cards-record', 1, 1792, 1, 0, 31, 27, 0, UNIX_TIMESTAMP(), UNIX_TIMESTAMP());
        SET @page = LAST_INSERT_ID();
        INSERT INTO tt_content (pid, CType, colPos, sorting, sys_language_uid, header, header_layout, header_tag, recordcards, crdate, tstamp)
            VALUES (@page, 'twtgroup_recordcards', 0, 256, 0, 'Our cards', 0, 'h2', 3, UNIX_TIMESTAMP(), UNIX_TIMESTAMP());
        SET @element = LAST_INSERT_ID();
        INSERT INTO recordcards (pid, sorting, title, tag, text, foreign_table_parent_uid, crdate, tstamp) VALUES
            (@page, 256, 'First card', 'h3', '<p>The first card has an H3.</p>', @element, UNIX_TIMESTAMP(), UNIX_TIMESTAMP()),
            (@page, 512, 'Second card', 'h3', '<p>The second card has an H3 as well.</p>', @element, UNIX_TIMESTAMP(), UNIX_TIMESTAMP()),
            (@page, 768, 'Third card', 'h4', '<h3>A heading in the text of a card</h3><p>An H4 right after an H2: a level is skipped.</p>', @element, UNIX_TIMESTAMP(), UNIX_TIMESTAMP());
    "
fi

echo "› finalising extensions and caches"
"${TYPO3_BIN}" extension:setup
"${TYPO3_BIN}" asset:publish || true
"${TYPO3_BIN}" cache:flush
# A fresh install can leave a stale empty page in the page cache; clear it directly.
mysql -h "${DB_HOST}" -P "${DB_PORT}" -u "${DB_USER}" -p"${DB_PASS}" "${DB_NAME}" -e "TRUNCATE cache_pages;" 2>/dev/null || true

cat <<EOF

Done.
  Frontend: ${BASE_URL}
  Backend:  ${BASE_URL}typo3/   (user: ${ADMIN_USER}  pass: ${ADMIN_PASS})
EOF
